<?php require_once __DIR__.'/../config/config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT * FROM admins WHERE username=?');$s->execute([trim($_POST['username'])]);$a=$s->fetch();if($a&&password_verify($_POST['password'],$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];go('admin/index.php');}$err='Invalid login details.';}?><!doctype html><html><head><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="container" style="max-width:420px;padding-top:12vh"><div class="admin-card"><h2>WatchesError Admin</h2><?php if($err):?><p class="text-danger"><?=e($err)?></p><?php endif;?><form method="post"><?=csrf_field()?><input class="form-control mb-3" name="username" placeholder="Username" required><input class="form-control mb-3" type="password" name="password" placeholder="Password" required><button class="btn btn-gold w-100">Login</button></form></div></div></body></html>